from taf.ul.kpi_selector.operations.factory_prototype.classical_factory_prototype import OperationFactoryPrototype
from taf.ul.kpi_selector.operations.gsm_rat_reset.classical_gsm_rat_reset.gsm_rat_reset_prototype import GsmRatReset


class GsmRatResetFactory(OperationFactoryPrototype):
    def __init__(self):
        super(GsmRatResetFactory, self).__init__()

    def get_kpi(self):
        """
        Gets kpi for GSM rat reset operation.
        :return: dictionary with timeout, requirement and operation description for GSM rat reset
        :rtype: dict
        """
        return GsmRatReset(self.bts).get_kpi()
